WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY order_date DESC, id) AS row_num FROM orders QUALIFY row_num = 1) SELECT s.id, s.customer_id, s.store_id, s.status, s.channel, s.amount, s.discount, s.shipping_fee, s.row_num, (SELECT MIN(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS min_inventory_quantity FROM deduped s ORDER BY customer_id DESC;
